"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["65067"],{43541(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fato_candidato.agregado_nao_tem_valores_proprios","status":422,"titulo":"Os valores do agregado s\xe3o os do fato de membro"},"descricao":{"codigo":"uniplus.configuracao.fato_candidato.agregado_nao_tem_valores_proprios","requisitos":["UNI-REQ-0146","UNI-REQ-0159"],"oQueAconteceu":["O administrador tentou acrescentar (`POST /api/configuracao/admin/fatos-candidato/{id}/valores`), corrigir (`PUT /api/configuracao/admin/fatos-candidato/{id}/valores/{codigo}`) ou reordenar (`PUT /api/configuracao/admin/fatos-candidato/{id}/ordem-dos-valores`) os valores de um fato categ\xf3rico que resume respostas de grupo. Esse fato re\xfane, para um grupo repet\xedvel como a composi\xe7\xe3o familiar, as respostas dos membros a outro fato, chamado fato de membro (UNI-REQ-0146). As op\xe7\xf5es do resumo de grupo s\xe3o as do fato de membro e s\xe3o mantidas nele: a API n\xe3o guarda valores pr\xf3prios no resumo de grupo. A mensagem da resposta diz qual \xe9 o fato de membro.","A recusa \xe9 do fato, e n\xe3o de um campo: a resposta n\xe3o traz a lista `errors`. As confer\xeancias seguem esta ordem: a busca do fato ([fato do candidato n\xe3o encontrado](/erros/uniplus.configuracao.fato_candidato.nao_encontrado)), a recusa de fato de sistema ([defini\xe7\xe3o do fato de sistema travada](/erros/uniplus.configuracao.fato_candidato.definicao_do_fato_de_sistema_travada)), a recusa de fato que n\xe3o \xe9 categ\xf3rico ([s\xf3 fato categ\xf3rico tem valores](/erros/uniplus.configuracao.fato_valor_dominio.nao_permitido_fora_de_categorico)) e, por fim, esta. O resumo de grupo booleano, que responde \\"existe membro que\u2026\\", \xe9 de outro tipo de dado e recebe a recusa de fato que n\xe3o \xe9 categ\xf3rico. Na desativa\xe7\xe3o e na reativa\xe7\xe3o de valor essas confer\xeancias n\xe3o rodam: o resumo de grupo n\xe3o tem o valor, e a resposta \xe9 a de [valor n\xe3o encontrado](/erros/uniplus.configuracao.fato_valor_dominio.nao_encontrado). Nada \xe9 gravado."],"comoResolver":["Fa\xe7a a opera\xe7\xe3o no fato de membro, onde as op\xe7\xf5es s\xe3o cadastradas: acrescente, corrija ou reordene os valores nele, e o resumo de grupo passa a refleti-los. O c\xf3digo do fato de membro vem na mensagem da resposta.","O resumo de grupo muda s\xf3 o ponto de resolu\xe7\xe3o e a prote\xe7\xe3o de dados (UNI-REQ-0159)."],"ondeAparece":["Acr\xe9scimo de um valor a um fato do cat\xe1logo","Corre\xe7\xe3o de um valor de um fato do cat\xe1logo","Reordena\xe7\xe3o dos valores de um fato do cat\xe1logo"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fato candidato"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);